public long phiByCount(long n) {
    long count = 0;
    for (long k = 1; k <= n; k++) {
        if (gcd(k, n) == 1) count++;
    }
    return count;
}

private long gcd(long a, long b) {
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

