public long phi(long n) {
    long result = n;
    long temp = n;
    for (long p = 2; p * p <= temp; p++) {
        if (temp % p == 0) {
            while (temp % p == 0) temp /= p;   // strip all copies
            result = result / p * (p - 1);     // distinct prime once
        }
    }
    if (temp > 1) {
        result = result / temp * (temp - 1);   // leftover large prime
    }
    return result;
}

