public int[] totientSieve(int n) {
    int[] phi = new int[n + 1];
    for (int i = 0; i <= n; i++) phi[i] = i;
    for (int i = 2; i <= n; i++) {
        if (phi[i] == i) {                 // i is prime
            for (int m = i; m <= n; m += i) {
                phi[m] -= phi[m] / i;      // multiply by (1 - 1/i)
            }
        }
    }
    return phi;
}

