def totient_sieve(self, n: int) -> list[int]:
    phi = list(range(n + 1))
    for i in range(2, n + 1):
        if phi[i] == i:                    # i is prime
            for m in range(i, n + 1, i):
                phi[m] -= phi[m] // i      # multiply by (1 - 1/i)
    return phi

